   var fast=PreferenceTransfer.Copy(pet.Settings);fast.AnimationSpeeds["groom"]=4;fast.AnimationSpeeds["stretch"]=4;var auto=new OutfitActionPreview(fast,false){Owner=settings};auto.Show();await Task.Delay(620);Check(((ComboBox)F(auto,"selection")).SelectedIndex==1,"real preview timer rotates through checked actions");auto.Close();var finish=new OutfitActionPreview(fast,false){Owner=settings};((CheckBox)F(finish,"cycle")).IsChecked=false;finish.Show();await Task.Delay(620);Check(!((DispatcherTimer)F(finish,"timer")).IsEnabled&&((TextBlock)F(finish,"status")).Text.Contains("完成"),"non-looping preview stops rendering after completion");SettingsWindow.Descendants<Button>(finish).Single(b=>Convert.ToString(b.Content)=="重播当前动作").RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Check(((DispatcherTimer)F(finish,"timer")).IsEnabled,"replay restarts a completed preview renderer");finish.Close();
