   passed=true;
  }catch(Exception e){Store.Atomic("error.json",new{error=e.ToString(),checks});}finally{MotionSettings.Reduced=false;foreach(var w in app.Windows.Cast<Window>().Where(w=>w!=pet).ToArray())w.Close();pet.Close();}};app.Run(pet);Store.Atomic("result.json",new{passed,checks,names});return passed?0:1;
